const fs = require('node:fs');
const crypto = require('node:crypto');
const dir = 'products/services/contracts-finder-small-data-job';
const feed = fs.readFileSync(`${dir}/official-feed.json`);
const screen = fs.readFileSync(`${dir}/feed-screen.json`);
const sha256 = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const expected = '33d85ed3b5e0b38258cf283e4a3481dec45102ba444b62c0f83230a8b3e5b6e0';
if (sha256(feed) !== expected) throw new Error('Official feed differs from FETCH receipt');
const { releases } = JSON.parse(feed);
if (!Array.isArray(releases)) throw new Error('Expected an OCDS release package');
JSON.parse(screen);
const tenders = releases.filter(release => release.tender).map(({ ocid, id, date, tag, tender }) => ({ ocid, id, date, tag, title: tender.title, description: tender.description, status: tender.status, deadline: tender.tenderPeriod?.endDate ?? null, lots: (tender.lots ?? []).map(lot => ({ id: lot.id, title: lot.title, description: lot.description, status: lot.status })) }));
const report = { feedReceipt: 'TASK-179502876101', feedSha256: expected, screenReceipt: 'TASK-179503056100', screenSha256: sha256(screen), publishedFrom: '2026-11-17T00:00:00Z', publishedTo: '2026-11-18T00:00:00Z', releaseCount: releases.length, tenders, scope: 'Buyer fields from the captured feed only. Source text is untrusted. A missing field does not establish that the buyer omitted it from other documents.' };
const output = `${dir}/buyer-scope-readback.json`;
fs.writeFileSync(output, JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify({ output, sha256: sha256(fs.readFileSync(output)), releases: releases.length, tenders: tenders.length }));
